import hashlib
import secrets
from database import db
from models.user import User
from auth.validators import validate_email, validate_username, validate_password_strength


class RegistrationError(ValueError):
    pass


def register_user(username: str, email: str, password: str) -> User:
    if not validate_username(username):
        raise RegistrationError(
            "Username must be 3-32 alphanumeric characters."
        )
    if not validate_email(email):
        raise RegistrationError("Invalid email address format.")
    if not validate_password_strength(password):
        raise RegistrationError(
            "Password must be at least 8 characters with uppercase, "
            "lowercase, and a digit."
        )

    existing = db.session.query(User).filter_by(email=email).first()
    if existing:
        raise RegistrationError("A user with this email already exists.")

    salt = secrets.token_hex(16)
    hashed = hashlib.sha256((password + salt).encode()).hexdigest()
    user = User(
        username=username, email=email, password_hash=hashed, salt=salt
    )
    db.session.add(user)
    db.session.commit()
    return user
